{{ config(materialized='view', schema='TIMELINE', alias='POLITICS__FED_CONGRESS_COMMITTEE_MEMBERSHIP') }}

-- Hand-written 2026-09-06, NOT generated by scripts/census/gen_time_views.py.
-- The mart had no timeline view because it had no date: it was a current-only
-- snapshot. It now carries one snapshot per congress with SNAPSHOT_DATE, so it
-- belongs on the shared timeline. Fold this into clock_index.csv when the
-- generator next runs, or the next regeneration will drop it.
--
-- Canonical clock for POLITICS.POLITICS__FED_CONGRESS_COMMITTEE_MEMBERSHIP.
--   column : SNAPSHOT_DATE   (TEXT, always ISO YYYY-MM-DD)
--   fmt    : 'iso' pinned, not 'auto'. The loader writes when[:10] off a git
--            commit timestamp, so the shape cannot vary, and pinning keeps the
--            compiled predicate small enough to read.
--   means  : reported -- the day the roster was READ out of the
--            committee-membership-current.yaml git history, not the day anyone
--            joined or left a committee.
--   grain  : day
--
-- WHY 'reported' AND NOT 'happened': nothing happened on this date. It is the
-- observation date of a snapshot. A member who joined in year two of a congress
-- and one who sat the whole term carry the identical SNAPSHOT_DATE, and a member
-- who left before it does not appear at all. Against Voteview the roster misses
-- 14 to 35 members per congress, about 4%, leaning toward mid-term deaths,
-- resignations and one expulsion. Read this axis as "the roster as of", never as
-- "was on the committee in <year>".
--
-- reported cannot be in the future -- if this row's value is, ripple_clock
-- reads 'planned' instead, not 'reported'. See ripple_row_clock in
-- macros/ripple_time.sql.
--
-- The original columns pass through untouched; the canonical four sit in front
-- of them. Rule 8 of the datetime standard: the raw column is never overwritten,
-- so a mis-parse is always recoverable.

select
    {{ ripple_ts_from_date('src."SNAPSHOT_DATE"', 'iso') }} as ripple_ts,
    {{ ripple_grain('day') }} as ripple_grain,
    {{ ripple_row_clock(ripple_ts_from_date('src."SNAPSHOT_DATE"', 'iso'), 'reported') }} as ripple_clock,
    'POLITICS.POLITICS__FED_CONGRESS_COMMITTEE_MEMBERSHIP'::varchar as ripple_source,
    src.*
from {{ ref('politics__fed_congress_committee_membership') }} as src
